// Fake Calendly events for Darwin Sessions Ingest, sent in order. Sessions are tomorrow,
// so PF Show-up Check never picks them up.
const run = $now.toFormat('HHmmss');
const CD = 'https://api.calendly.com/event_types/ebd64db8-7c09-4e31-bc2e-339065fbb930';
const OTHER = 'https://api.calendly.com/event_types/MOCK-ET-RESEARCH-OTHER';
const inv = (c) => `https://api.calendly.com/scheduled_events/MOCK-EVT-SI-${c}-${run}/invitees/MOCK-INV-SI-${c}-${run}`;
const evt = (c) => `https://api.calendly.com/scheduled_events/MOCK-EVT-SI-${c}-${run}`;
const start = $now.plus({ days: 1 }).set({ hour: 10, minute: 0, second: 0, millisecond: 0 });
const end = start.plus({ minutes: 30 });
const UXR = { utm_source: 'uxr_recruiting', utm_medium: 'email', utm_campaign: `batch_mock-si-${run}` };
const QA = [{ question: 'What do you use n8n for?', answer: 'Mock answer' }, { question: 'Company size', answer: '11-50' }];

function payload(c, first, tag, o = {}) {
  return {
    uri: inv(c), email: o.email ?? `aniol.moner+${tag}@n8n.io`, name: `${first} Mock`, first_name: first, last_name: 'Mock',
    status: o.cancel ? 'canceled' : 'active', timezone: 'Europe/Madrid',
    rescheduled: o.rescheduled ?? false, old_invitee: o.old ?? null, new_invitee: o.new ?? null,
    reschedule_url: `https://calendly.com/reschedulings/MOCK-SI-${c}`, cancel_url: `https://calendly.com/cancellations/MOCK-SI-${c}`,
    cancellation: o.cancel ? { canceled_by: `${first} Mock`, canceler_type: 'invitee', reason: o.cancel, created_at: $now.toISO() } : null,
    no_show: null, tracking: o.tracking ?? {}, questions_and_answers: QA,
    scheduled_event: {
      uri: evt(c), name: o.name ?? 'Research with n8n', event_type: o.et ?? CD,
      start_time: start.toUTC().toISO(), end_time: end.toUTC().toISO(), status: o.cancel ? 'canceled' : 'active',
      event_memberships: [{ user: 'https://api.calendly.com/users/MOCK-HOST', user_email: 'aniol.moner@n8n.io', user_name: 'Aniol Moner' }],
    },
  };
}
const created = (p, label) => ({ json: { _label: label, event: 'invitee.created', payload: p } });
const canceled = (p, label) => ({ json: { _label: label, event: 'invitee.canceled', payload: p } });
const R = { et: OTHER, name: 'Aniol research interview' };

return [
  created(payload('A', 'Ada', 'si-a'), 'A: CD event, no utm -> continuous_discovery / continuous_discovery'),
  created(payload('B', 'Ben', 'si-b', { tracking: UXR }), 'B: CD event WITH recruiting utm -> still continuous_discovery, source uxr_recruiting'),
  created(payload('C', 'Cleo', 'si-c', { ...R, tracking: UXR }), 'C: other event, recruiting utm -> research / uxr_recruiting'),
  created(payload('D', 'Dev', 'si-d', R), 'D: other event, no utm -> research / research'),
  canceled(payload('D', 'Dev', 'si-d', { ...R, cancel: 'Cannot make it' }), 'E: cancel D -> canceled, canceled_at, reason'),
  created(payload('F1', 'Fay', 'si-f'), 'F1: CD original'),
  canceled(payload('F1', 'Fay', 'si-f', { cancel: 'Rescheduled', rescheduled: true, new: inv('F2') }), 'F1 canceled as rescheduled'),
  created(payload('F2', 'Fay', 'si-f', { old: inv('F1') }), 'F2: new booking -> F1 rescheduled + canceled_at, F2 active'),
  created(payload('G1', 'Gus', 'si-g'), 'G1: CD original (out of order test)'),
  created(payload('G2', 'Gus', 'si-g', { old: inv('G1') }), 'G2 arrives before the cancel -> G1 rescheduled + canceled_at'),
  canceled(payload('G1', 'Gus', 'si-g', { cancel: 'Rescheduled', rescheduled: true, new: inv('G2') }), 'G1 cancel last -> still rescheduled'),
  created(payload('A', 'Ada', 'si-a'), 'I: duplicate of A -> still one row'),
  created(payload('H', 'Hal', 'si-h', { email: 'hal.real.person@example.com' }), 'H: non-mock email -> dropped'),
];
